package org.apache.commons.lang;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class LocaleUtils_toLocale_TriageGen1Test {

    @Test
    public void testToLocale_Null() {
        assertNull(LocaleUtils.toLocale(null));
    }

    @Test
    public void testToLocale_ValidLanguageOnly() {
        Locale result = LocaleUtils.toLocale("en");
        assertEquals("en", result.getLanguage());
        assertEquals("", result.getCountry());
    }

    @Test
    public void testToLocale_ValidLanguageAndCountry() {
        Locale result = LocaleUtils.toLocale("en_US");
        assertEquals("en", result.getLanguage());
        assertEquals("US", result.getCountry());
    }

    @Test
    public void testToLocale_ValidLanguageAndCountryAndVariant() {
        Locale result = LocaleUtils.toLocale("en_US_POSIX");
        assertEquals("en", result.getLanguage());
        assertEquals("US", result.getCountry());
        assertEquals("POSIX", result.getVariant());
    }

    @Test
    public void testToLocale_InvalidLength() {
        // len 1
        try {
            LocaleUtils.toLocale("e");
            fail("Should throw IllegalArgumentException");
        } catch (IllegalArgumentException e) {
            assertEquals("Invalid locale format: e", e.getMessage());
        }

        // len 3
        try {
            LocaleUtils.toLocale("en_");
            fail("Should throw IllegalArgumentException");
        } catch (IllegalArgumentException e) {
            assertEquals("Invalid locale format: en_", e.getMessage());
        }

        // len 4
        try {
            LocaleUtils.toLocale("en_U");
            fail("Should throw IllegalArgumentException");
        } catch (IllegalArgumentException e) {
            assertEquals("Invalid locale format: en_U", e.getMessage());
        }

        // len 6
        try {
            LocaleUtils.toLocale("en_US_P");
            fail("Should throw IllegalArgumentException");
        } catch (IllegalArgumentException e) {
            assertEquals("Invalid locale format: en_US_P", e.getMessage());
        }
    }

    @Test
    public void testToLocale_InvalidLanguageChars() {
        // Non-lowercase language
        try {
            LocaleUtils.toLocale("EN");
            fail("Should throw IllegalArgumentException");
        } catch (IllegalArgumentException e) {
            assertEquals("Invalid locale format: EN", e.getMessage());
        }

        // Non-alpha language
        try {
            LocaleUtils.toLocale("e1");
            fail("Should throw IllegalArgumentException");
        } catch (IllegalArgumentException e) {
            assertEquals("Invalid locale format: e1", e.getMessage());
        }
    }

    @Test
    public void testToLocale_InvalidSeparator() {
        // Missing underscore for length 5
        try {
            LocaleUtils.toLocale("enUS");
            fail("Should throw IllegalArgumentException");
        } catch (IllegalArgumentException e) {
            assertEquals("Invalid locale format: enUS", e.getMessage());
        }
    }

    @Test
    public void testToLocale_InvalidCountryChars() {
        // Non-uppercase country
        try {
            LocaleUtils.toLocale("en_us");
            fail("Should throw IllegalArgumentException");
        } catch (IllegalArgumentException e) {
            assertEquals("Invalid locale format: en_us", e.getMessage());
        }

        // Non-alpha country
        try {
            LocaleUtils.toLocale("en_U1");
            fail("Should throw IllegalArgumentException");
        } catch (IllegalArgumentException e) {
            assertEquals("Invalid locale format: en_U1", e.getMessage());
        }
    }

    @Test
    public void testToLocale_InvalidVariantSeparator() {
        // Missing second underscore for length > 5
        try {
            LocaleUtils.toLocale("en_US_POSIX"); // Wait, the logic checks index 5 for '_'
            // If len is 10, index 5 must be '_'
            LocaleUtils.toLocale("enUS_POSIX"); // This is len 10, but ch2 is 'U', not '_'
            fail("Should throw IllegalArgumentException");
        } catch (IllegalArgumentException e) {
            // This falls into the "str.charAt(2) != '_'" check
        }

        try {
            LocaleUtils.toLocale("en_USPOSIX"); // len 9, index 5 is 'P'
            fail("Should throw IllegalArgumentException");
        } catch (IllegalArgumentException e) {
            assertEquals("Invalid locale format: en_USPOSIX", e.getMessage());
        }
    }
}
